import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();sc.nextLine();String[]recs=new String[n];for(int i=0;i<n;i++)recs[i]=sc.nextLine().trim();String dest=sc.nextLine().trim();boolean found=false;for(String r:recs){String[]f=r.split(" ");if(f.length>1&&f[1].equals(dest)){System.out.println(r);found=true;}}if(!found)System.out.println("No Flights Found");}}
